From aa55d4fa23dbcd5cf43417a37e544b051a878c2b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:59:58 +0100
Subject: [PATCH] containments/desktop: update the drag image when a dragged
 icon changes

A thumbnail that arrived while its file was dragged only showed after
the drop, because the drag image was grabbed once. Keep dragged items'
delegates loaded and regrab them when their icon changes mid-drag.

BUG: 518070
---
 .../package/contents/ui/FolderItemDelegate.qml      | 13 ++++++++++---
 containments/desktop/plugins/folder/foldermodel.cpp |  9 ++++++++-
 containments/desktop/plugins/folder/foldermodel.h   |  2 ++
 3 files changed, 20 insertions(+), 4 deletions(-)

diff --git a/containments/desktop/package/contents/ui/FolderItemDelegate.qml b/containments/desktop/package/contents/ui/FolderItemDelegate.qml
index 2676ceaeec..38a341490e 100644
--- a/containments/desktop/package/contents/ui/FolderItemDelegate.qml
+++ b/containments/desktop/package/contents/ui/FolderItemDelegate.qml
@@ -82,17 +82,24 @@ Item {
         width: parent.width
         height: parent.height

-        visible: status === Loader.Ready
+        visible: status === Loader.Ready && !main.blank

-        active: !main.blank
+        // Keep dragged items loaded, so their drag image can be updated
+        active: !main.blank || main.selected

         sourceComponent: delegateImplementation

         asynchronous: true
     }

+    onDecorationChanged: {
+        if (blank) {
+            Qt.callLater(main.updateDragImage);
+        }
+    }
+
     function updateDragImage() {
-        if (selected && !blank) {
+        if (selected && loader.item) {
             main.dragImageBeingGenerated = true;
             loader.grabToImage(result => {
                 dir.addItemDragImage(positioner.map(index), main.x + loader.x, main.y + loader.y, loader.width, loader.height, result.image);
diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..8ddaecd998 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -1133,6 +1133,10 @@ void FolderModel::addItemDragImage(int row, int x, int y, int width, int height,
     dragImage->blank = false;

     m_dragImages.insert(row, dragImage);
+
+    if (m_drag && m_dragIndexes.contains(index(row, 0))) {
+        addDragImage(m_drag, m_dragHotSpot.x(), m_dragHotSpot.y());
+    }
 }

 void FolderModel::clearDragImages()
@@ -1168,7 +1172,7 @@ void FolderModel::addDragImage(QDrag *drag, int x, int y)
     QRegion region;

     for (DragImage *image : std::as_const(m_dragImages)) {
-        image->blank = isBlank(image->row);
+        image->blank = !m_dragIndexes.contains(index(image->row, 0)) && isBlank(image->row);
         image->rect.translate(-m_dragHotSpotScrollOffset.x(), -m_dragHotSpotScrollOffset.y());
         if (!image->blank && !image->image.isNull()) {
             region = region.united(image->rect);
@@ -1233,6 +1237,8 @@ void FolderModel::dragSelectedInternal(int x, int y)
     QDrag *drag = new QDrag(item);

     addDragImage(drag, x, y);
+    m_drag = drag;
+    m_dragHotSpot = QPoint(x, y);

     m_dragIndexes = m_selectionModel->selectedIndexes();

@@ -1259,6 +1265,7 @@ void FolderModel::dragSelectedInternal(int x, int y)

     item->grabMouse();
     drag->exec(supportedDragActions());
+    m_drag = nullptr;

     item->ungrabMouse();

diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..e917911fd6 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -378,6 +378,8 @@ private:
     QModelIndexList m_dragIndexes;
     QHash<int, DragImage *> m_dragImages;
     QPoint m_dragHotSpotScrollOffset;
+    QPointer<QDrag> m_drag;
+    QPoint m_dragHotSpot;
     bool m_urlChangedWhileDragging;
     // target filename to target position of a drop event, note that this deliberately
     // is not using the URL to easily support desktop:/ URL schemes
-- 
2.53.0

From b1408c0fe4eff44e3d63eeac55a789f9e75b47ad Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:59:58 +0100
Subject: [PATCH] QDrag: update the drag icon when setPixmap() is called during
 a drag

The pixmap was only read when the drag started, so an application could
not change the picture under the pointer while dragging. Let QBasicDrag
repaint its drag icon window when the running drag's pixmap changes.
---
 src/gui/kernel/qdrag.cpp       |  5 +++++
 src/gui/kernel/qsimpledrag.cpp | 15 +++++++++++++++
 src/gui/kernel/qsimpledrag_p.h |  1 +
 3 files changed, 21 insertions(+)

diff --git a/src/gui/kernel/qdrag.cpp b/src/gui/kernel/qdrag.cpp
index 7399e9c0..4a6fa842 100644
--- a/src/gui/kernel/qdrag.cpp
+++ b/src/gui/kernel/qdrag.cpp
@@ -9,6 +9,7 @@
 #include <qpixmap.h>
 #include <qpoint.h>
 #include "qdnd_p.h"
+#include "qsimpledrag_p.h"

 #include <QtCore/qpointer.h>

@@ -133,6 +134,10 @@ void QDrag::setPixmap(const QPixmap &pixmap)
 {
     Q_D(QDrag);
     d->pixmap = pixmap;
+    if (QDragManager::m_instance && QDragManager::m_instance->object() == this) {
+        if (auto *basicDrag = dynamic_cast<QBasicDrag *>(QGuiApplicationPrivate::platformIntegration()->drag()))
+            basicDrag->updatePixmap();
+    }
 }

 /*!
diff --git a/src/gui/kernel/qsimpledrag.cpp b/src/gui/kernel/qsimpledrag.cpp
index 10ca9073..188b9f33 100644
--- a/src/gui/kernel/qsimpledrag.cpp
+++ b/src/gui/kernel/qsimpledrag.cpp
@@ -237,6 +237,21 @@ void QBasicDrag::recreateShapedPixmapWindow(QScreen *screen, const QPoint &pos)
     m_drag_icon_window->setVisible(true);
 }

+void QBasicDrag::updatePixmap()
+{
+    if (!m_drag || !m_drag_icon_window)
+        return;
+
+    QPoint pos;
+#ifndef QT_NO_CURSOR
+    pos = QCursor::pos();
+#endif
+    m_drag_icon_window->setPixmap(m_drag->pixmap());
+    m_drag_icon_window->setHotspot(m_drag->hotSpot());
+    m_drag_icon_window->updateGeometry(pos);
+    m_drag_icon_window->update();
+}
+
 void QBasicDrag::cancel()
 {
     disableEventFilter();
diff --git a/src/gui/kernel/qsimpledrag_p.h b/src/gui/kernel/qsimpledrag_p.h
index fb536a92..63c0751a 100644
--- a/src/gui/kernel/qsimpledrag_p.h
+++ b/src/gui/kernel/qsimpledrag_p.h
@@ -41,6 +41,7 @@ public:

     virtual Qt::DropAction drag(QDrag *drag) override;
     void cancelDrag() override;
+    void updatePixmap();

     virtual bool eventFilter(QObject *o, QEvent *e) override;

-- 
